<script setup>
import { computed, ref } from 'vue'
import { svgReference } from '@/data/svgReference'
import DisclosureCard from '@/components/DisclosureCard.vue'
import RichText from '@/components/RichText.vue'
const items = svgReference
const active = ref(null)
const selected = computed(() => items.find((item) => item.id === active.value))
function select(id) { active.value = active.value === id ? null : id }
</script>

<template><div class="flex flex-col gap-6"><header><h1 class="text-2xl font-extrabold text-slate-900">Справочник SVG</h1><p class="mt-1 text-slate-500">Интерактивная мини-схема: выберите тег в коде, на рисунке или в карточке.</p></header><div v-if="selected" class="sticky top-20 z-10 flex items-center justify-between gap-3 rounded-xl bg-slate-900 px-4 py-3 text-sm text-white shadow-lg"><code>&lt;{{ selected.tag }}&gt;</code><button class="rounded-lg bg-white/10 px-3 py-1.5 font-semibold hover:bg-white/20" @click="active = null">Снять выделение</button></div><section class="card p-5"><svg viewBox="0 0 560 200" class="w-full" role="group" aria-label="Интерактивная схема маршрута"><g role="button" tabindex="0" aria-label="Выбрать группу SVG" :aria-pressed="active === 'g'" @keydown.enter.stop.prevent="select('g')" @keydown.space.stop.prevent="select('g')" @click="select('g')" class="cursor-pointer"><path role="button" tabindex="0" aria-label="Выбрать маршрут path" :aria-pressed="active === 'path'" @click.stop="select('path')" @keydown.enter.stop.prevent="select('path')" @keydown.space.stop.prevent="select('path')" d="M70 140 C160 30 270 180 470 60" fill="none" stroke="currentColor" stroke-width="8" class="text-slate-300" :class="active === 'path' || active === 'g' || active === 'svg' ? 'text-brand-500' : ''"/><circle role="button" tabindex="0" aria-label="Выбрать круг circle" :aria-pressed="active === 'circle'" @keydown.enter.stop.prevent="select('circle')" @keydown.space.stop.prevent="select('circle')" v-for="(point, index) in [[70,140],[270,110],[470,60]]" :key="index" :cx="point[0]" :cy="point[1]" r="18" class="cursor-pointer fill-white stroke-slate-700" :class="active === 'circle' || active === 'g' || active === 'svg' ? 'stroke-brand-500' : ''" stroke-width="6" @click.stop="select('circle')"/></g></svg><div class="mt-4 rounded-xl bg-slate-950 p-4 font-mono text-sm leading-7 text-slate-300"><button @click="select('svg')" :class="active === 'svg' ? 'rounded bg-slate-700' : ''">&lt;svg viewBox="0 0 560 200"&gt;</button><br><span class="pl-4"><button @click="select('g')" :class="active === 'g' ? 'rounded bg-slate-700' : ''">&lt;g&gt;</button></span><br><span class="pl-8"><button @click="select('path')" :class="active === 'path' ? 'rounded bg-slate-700' : ''">&lt;path d="…" /&gt;</button></span><br><span class="pl-8"><button @click="select('circle')" :class="active === 'circle' ? 'rounded bg-slate-700' : ''">&lt;circle cx="…" cy="…" r="18" /&gt;</button></span><br><span class="pl-4">&lt;/g&gt;</span><br>&lt;/svg&gt;</div></section><section class="flex flex-col gap-3"><DisclosureCard v-for="item in items" :id="'svg-' + item.id" :key="item.id" :open="active === item.id" @toggle="select(item.id)"><template #heading><code class="mr-3 rounded bg-slate-100 px-2 py-1 text-fuchsia-700">&lt;{{ item.tag }}&gt;</code><span class="font-semibold">{{ item.title }}</span></template><div class="text-sm text-slate-600"><RichText :text="item.text" /></div><p class="mt-3 text-sm text-slate-500">Связанная карточка: {{ item.cardQuestion }}</p><a class="mt-4 inline-flex min-h-11 items-center text-sm font-semibold text-brand-700 hover:underline" :href="item.mdn" target="_blank" rel="noreferrer">Подробнее на MDN Web Docs ↗</a></DisclosureCard></section></div></template>
